{"fingerprint":"1c26cfdb585bb2dca67062ac850e524185c3c17c01629d160f54ff2324c4b37f","path":"src/review_gauntlet/cli.py","rule_id":"data-validation","content":"`_positive_int` calls `int(value)` directly, so a non-integer value such as `--max-steps abc` raises an uncaught `ValueError` and prints a traceback instead of argparse's normal usage error. Wrap the conversion and raise `argparse.ArgumentTypeError` so invalid user input is reported consistently.","suggestion_code":"def _positive_int(value: str) -> int:
    try:
        parsed = int(value)
    except ValueError as exc:
        raise argparse.ArgumentTypeError("must be an integer") from exc
    if parsed < 1:
        raise argparse.ArgumentTypeError("must be a positive integer")
    return parsed","existing_code":"def _positive_int(value: str) -> int:
    parsed = int(value)
    if parsed < 1:
        raise argparse.ArgumentTypeError("must be a positive integer")
    return parsed","start_line":332,"end_line":333,"thinking":"This is a data validation issue in CLI argument parsing. argparse type functions should convert invalid input into ArgumentTypeError; otherwise malformed input escapes as an internal exception.","imprecise":false}

{"fingerprint":"a1a19eab9366c45de7df7165817e9ddebb424d363fd5a3581a9d878493c4fd51","path":"src/review_gauntlet/run_tui.py","rule_id":"cli-contract","content":"The TUI schedules the full controller run on the Textual UI thread. Because controller.run() can execute long-running external review commands synchronously, the event loop is blocked while a step runs, so documented TUI controls such as q/refresh/Ctrl-C cannot be processed until after the command returns. This breaks the interactive CLI contract for stopping or interrupting a running review from the TUI.","suggestion_code":"        def on_mount(self) -> None:
            self.refresh_view()
            self.run_worker(self._run_controller, thread=True)

        def _run_controller(self) -> None:
            self.call_from_thread(self.exit, self.controller.run())","existing_code":"        def on_mount(self) -> None:
            self.refresh_view()
            self.call_later(self._run_controller)

        def _run_controller(self) -> None:
            self.exit(self.controller.run())","start_line":67,"end_line":72,"thinking":"call_later keeps the blocking controller.run() on the UI event loop. Running it in a worker thread keeps Textual responsive so key bindings can request stop/interrupt while the run is active.","imprecise":false}

