{"fingerprint":"ad845545b67c7f693bebaaf99e6c8831ab9831cf8127560feace522a0025c209","path":"src/review_gauntlet/run_tui.py","rule_id":"test-evidence","content":"The TUI sanitizes the current task text, but other user- or adapter-controlled strings are rendered directly. command_argv and event payload values can contain Textual/Rich markup or control characters, which may alter the display or hide content in the TUI. Apply the same plain-text normalization used for task prompts before rendering argv and event payloads.","suggestion_code":"def _agent_text(snapshot: RunSnapshot) -> str:
    argv = _plain_text(" ".join(snapshot.command_argv)) if snapshot.command_argv else "n/a"
    return (
        "Agent\n"
        f"status={_plain_text(snapshot.agent_status)} step={snapshot.step} "
        f"elapsed={snapshot.elapsed_seconds:.1f}s\nargv={argv}"
    )


def _events_text(events: tuple[RunEvent, ...]) -> str:
    lines = ["Events"]
    for event in events[-12:]:
        payload = " ".join(
            f"{_plain_text(key)}={_plain_text(value)}" for key, value in event.payload.items()
        )
        lines.append(
            f"{event.timestamp} {_plain_text(event.type)} {payload}".rstrip()
        )
    return "\n".join(lines)","existing_code":"def _agent_text(snapshot: RunSnapshot) -> str:
