        lines.append(f"{event.timestamp} {event.type} {payload}".rstrip())
    return "\n".join(lines)","start_line":130,"end_line":144,"thinking":"_task_text explicitly escapes markup/control characters, but adjacent TUI panels do not. These values can originate from config, adapter output, or runtime events and are displayed as Textual Static strings.","imprecise":false}

